// Deploy check program for the Datadog MCP `execute_code`. Generated by `ws deploy-check script`:
// the only line that changes is the one with the parameters. Read-only: aggregate queries only.
const P = /*ws:params*/null;

const REL_LIMIT = 0.5;
const P95_REL_LIMIT = 0.3;
const P95_ABS_LIMIT_MS = 50;
const WORSE_COUNT = 10;
const EPSILON = 1e-9;
const NS_PER_MS = 1e6;
const SEVERITY = { sem_dados: 0, ok: 1, atencao: 2, piorou: 3 };
const SIGNATURE_LIMIT = 50;
const SIGNATURE_SHOWN = 10;
const SIGNATURE_CHARS = 100;

function rate(count, minutes) {
  return minutes > 0 ? count / minutes : 0;
}

function rise(before, after) {
  if (before === 0) return after > 0 ? Infinity : 0;
  return (after - before) / before;
}

function round(value, digits = 2) {
  if (value === null || value === undefined || !Number.isFinite(value)) return null;
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
}

function judgeRate(before, after, minRequests) {
  if (before.total < minRequests || after.total < minRequests) return "sem_dados";
  if (before.bad === 0) {
    if (after.bad === 0) return "ok";
    return after.bad >= WORSE_COUNT ? "piorou" : "atencao";
  }
  const change = rise(before.bad / before.total, after.bad / after.total);
  return change > REL_LIMIT + EPSILON ? "piorou" : "ok";
}

function judgeLogs(before, after) {
  const change = rise(rate(before.count, before.minutes), rate(after.count, after.minutes));
  if (change <= REL_LIMIT + EPSILON) return "ok";
  return after.count >= WORSE_COUNT ? "piorou" : "atencao";
}

function judgeLatency(before, after, minRequests, requests) {
  if (requests.before < minRequests || requests.after < minRequests) return "sem_dados";
  if (before === null || after === null) return "sem_dados";
  const worse = after > before * (1 + P95_REL_LIMIT) + EPSILON && after - before > P95_ABS_LIMIT_MS;
  return worse ? "piorou" : "ok";
}

function newErrors(after, baseline, source) {
  const known = new Set(baseline.map((item) => item.signature));
  return after
    .filter((item) => !known.has(item.signature))
    .map((item) => ({ signature: item.signature, count: item.count, source }));
}

function judgeNewErrors(list) {
  if (list.length === 0) return "ok";
  return list.some((item) => item.count >= WORSE_COUNT) ? "piorou" : "atencao";
}

function versionShare(byVersion, expected) {
  const total = Object.values(byVersion).reduce((sum, count) => sum + count, 0);
  if (total === 0 || !expected) return { total, share: null };
  return { total, share: (byVersion[expected] || 0) / total };
}

function verdict(checks) {
  const states = Object.values(checks).map((check) => check.status);
  return states.reduce((worst, state) => (SEVERITY[state] > SEVERITY[worst] ? state : worst), "sem_dados");
}

function lostQuery(raw, failed, names) {
  const lost = names.filter((name) => !(name in raw));
  if (lost.length === 0) return null;
  return "consulta falhou: " + (failed[lost[0]] || "sem resposta");
}

function noData(note) {
  return { status: "sem_dados", note };
}

function summarize(raw, failed) {
  const W = P.windows;
  const minutes = { before: W.before.minutes, after: W.after.minutes };
  const checks = {};
  const found = [];

  for (const name of P.checks) {
    if (name === "traffic") {
      const lost = lostQuery(raw, failed, ["traffic.b", "traffic.a"]);
      if (lost) { checks[name] = noData(lost); continue; }
      const low = raw["traffic.b"] < P.min_requests || raw["traffic.a"] < P.min_requests;
      checks[name] = {
        status: low ? "sem_dados" : "ok",
        before: round(rate(raw["traffic.b"], minutes.before), 1),
        after: round(rate(raw["traffic.a"], minutes.after), 1),
        unit: "req/min",
      };
    } else if (name === "errors" || name === "http_5xx") {
      const lost = lostQuery(raw, failed, [name + ".b", name + ".a", "traffic.b", "traffic.a"]);
      if (lost) { checks[name] = noData(lost); continue; }
      const before = { bad: raw[name + ".b"], total: raw["traffic.b"] };
      const after = { bad: raw[name + ".a"], total: raw["traffic.a"] };
      checks[name] = {
        status: judgeRate(before, after, P.min_requests),
        before: round((100 * before.bad) / Math.max(before.total, 1)),
        after: round((100 * after.bad) / Math.max(after.total, 1)),
        unit: "%",
      };
    } else if (name === "p95") {
      const lost = lostQuery(raw, failed, ["p95.b", "p95.a", "traffic.b", "traffic.a"]);
      if (lost) { checks[name] = noData(lost); continue; }
      const requests = { before: raw["traffic.b"], after: raw["traffic.a"] };
      checks[name] = {
        status: judgeLatency(raw["p95.b"], raw["p95.a"], P.min_requests, requests),
        before: round(raw["p95.b"], 1),
        after: round(raw["p95.a"], 1),
        unit: "ms",
      };
    } else if (name === "error_logs") {
      const lost = lostQuery(raw, failed, ["error_logs.b", "error_logs.a"]);
      if (lost) { checks[name] = noData(lost); continue; }
      checks[name] = {
        status: judgeLogs(
          { count: raw["error_logs.b"], minutes: minutes.before },
          { count: raw["error_logs.a"], minutes: minutes.after },
        ),
        before: round(rate(raw["error_logs.b"], minutes.before)),
        after: round(rate(raw["error_logs.a"], minutes.after)),
        unit: "logs/min",
      };
    } else if (name === "new_errors") {
      const sources = ["logs", "spans", "rum"].filter(
        (source) => ("new_errors_" + source + ".a") in raw || ("new_errors_" + source + ".a") in failed,
      );
      const lost = [];
      for (const source of sources) {
        const keys = ["new_errors_" + source + ".a", "new_errors_" + source + ".base"];
        const problem = lostQuery(raw, failed, keys);
        if (problem) lost.push(problem);
        else found.push(...newErrors(raw[keys[0]], raw[keys[1]], source));
      }
      if (lost.length === sources.length) { checks[name] = noData(lost[0]); continue; }
      found.sort((a, b) => b.count - a.count);
      checks[name] = {
        status: judgeNewErrors(found),
        after: found.length,
        unit: "new signatures",
        note: lost.length ? lost[0] : undefined,
      };
    } else if (name === "version") {
      const lost = lostQuery(raw, failed, ["version.a"]);
      if (lost) { checks[name] = noData(lost); continue; }
      const seen = versionShare(raw["version.a"], P.expected_version);
      let status = "sem_dados";
      let note;
      if (!P.expected_version) note = "versão esperada desconhecida";
      else if (seen.share !== null) status = seen.share >= 0.95 ? "ok" : "atencao";
      checks[name] = {
        status,
        after: round(seen.share === null ? null : 100 * seen.share, 1),
        unit: "% expected",
        note,
      };
    }
  }

  const shown = found.slice(0, SIGNATURE_SHOWN).map((item) => ({
    signature: String(item.signature).slice(0, SIGNATURE_CHARS),
    count: item.count,
    source: item.source,
  }));
  const version = checks.version;
  return {
    service: P.service,
    env: P.env_tag,
    complete: P.after_complete,
    expected_version: P.expected_version,
    version_share_pct: version && version.after !== undefined ? version.after : null,
    verdict: verdict(checks),
    checks,
    new_errors: shown,
    new_errors_total: found.length,
  };
}

function buckets(response) {
  const data = response && response.data;
  if (Array.isArray(data)) return data;
  return (data && data.buckets) || [];
}

function bucketBy(bucket) {
  return bucket.by || (bucket.attributes && bucket.attributes.by) || {};
}

function bucketValue(bucket) {
  const attributes = bucket.attributes || {};
  const computes = bucket.computes || attributes.computes || attributes.compute || bucket.compute || {};
  const value = computes.c0;
  return value === undefined || value === null ? null : Number(value);
}

function totalOf(response) {
  const first = buckets(response)[0];
  return first ? bucketValue(first) || 0 : 0;
}

function queries(api) {
  const W = P.windows;
  const base = ["service:" + P.service, "env:" + P.env_tag];
  const spanQuery = (...extra) => [...base, P.span_filter, ...extra].filter(Boolean).join(" ");
  const plainQuery = (...extra) => [...base, ...extra].filter(Boolean).join(" ");
  const range = (win) => ({ from: String(win.from_ms), to: String(win.to_ms) });
  const count = { aggregation: "count", type: "total" };
  const byCount = { type: "measure", aggregation: "count", order: "desc" };
  const windows = { b: W.before, a: W.after, base: W.baseline };
  const has = (name) => P.checks.includes(name);
  const rum = P.kind === "rum";
  const jobs = {};

  const counter = (call, query) => async (win) =>
    totalOf(await call({ compute: [count], filter: { query, ...range(win) } }));
  const grouped = (call, query, facets) => async (win) => {
    const response = await call({
      compute: [count],
      filter: { query, ...range(win) },
      groupBy: facets.map((facet, i) => ({ facet, limit: SIGNATURE_LIMIT, ...(i === 0 ? { sort: byCount } : {}) })),
    });
    return buckets(response).map((bucket) => ({
      signature: facets.map((facet) => String(bucketBy(bucket)[facet] ?? "?")).join(" | "),
      count: bucketValue(bucket) || 0,
    }));
  };
  const add = (name, win, job) => {
    jobs[name + "." + win] = () => job(windows[win]);
  };

  const entry = rum ? api.rum : api.spans;
  const entryQuery = rum ? plainQuery : spanQuery;
  const views = rum ? "@type:view" : null;
  const bad = rum ? "@type:error" : "status:error";

  if (P.kind !== "logs") {
    for (const win of ["b", "a"]) {
      add("traffic", win, counter(entry, entryQuery(views)));
      if (has("errors")) add("errors", win, counter(entry, entryQuery(bad)));
      if (has("http_5xx")) add("http_5xx", win, counter(entry, entryQuery("@http.status_code:[500 TO 599]")));
      if (has("p95")) {
        add("p95", win, async (w) => {
          const response = await api.spans({
            compute: [{ aggregation: "pc95", metric: "@duration", type: "total" }],
            filter: { query: spanQuery(), ...range(w) },
          });
          const first = buckets(response)[0];
          const value = first ? bucketValue(first) : null;
          return value === null ? null : value / NS_PER_MS;
        });
      }
    }
    if (has("version")) {
      add("version", "a", async (win) => {
        const response = await entry({
          compute: [count],
          filter: { query: entryQuery(views), ...range(win) },
          groupBy: [{ facet: P.version_facet, limit: SIGNATURE_LIMIT, sort: byCount }],
        });
        const out = {};
        for (const bucket of buckets(response)) out[String(bucketBy(bucket)[P.version_facet])] = bucketValue(bucket) || 0;
        return out;
      });
    }
  }
  if (!rum && has("error_logs")) {
    for (const win of ["b", "a"]) add("error_logs", win, counter(api.logs, plainQuery("status:error")));
  }
  if (has("new_errors")) {
    for (const win of ["a", "base"]) {
      if (!rum) add("new_errors_logs", win, grouped(api.logs, plainQuery("status:error"), ["@error.kind"]));
      if (P.kind === "apm") {
        add("new_errors_spans", win, grouped(api.spans, spanQuery("status:error"), ["resource_name", "@error.type"]));
      }
      if (rum) add("new_errors_rum", win, grouped(api.rum, plainQuery("@type:error"), ["@error.type", "@view.url_path_group"]));
    }
  }
  return jobs;
}

async function run(api) {
  const jobs = queries(api);
  const names = Object.keys(jobs);
  const settled = await Promise.allSettled(names.map((name) => jobs[name]()));
  const raw = {};
  const failed = {};
  names.forEach((name, i) => {
    const outcome = settled[i];
    if (outcome.status === "fulfilled") raw[name] = outcome.value;
    else failed[name] = String((outcome.reason && outcome.reason.message) || outcome.reason).slice(0, 120);
  });
  return summarize(raw, failed);
}

// ws:entry
const sdk = await import("@datadog/datadog-api-client");
const configuration = sdk.client.createConfiguration();
const spansApi = new sdk.v2.SpansApi(configuration);
const logsApi = new sdk.v2.LogsApi(configuration);
const rumApi = new sdk.v2.RUMApi(configuration);
return await run({
  spans: (attributes) => spansApi.aggregateSpans({ body: { data: { type: "aggregate_request", attributes } } }),
  logs: (body) => logsApi.aggregateLogs({ body }),
  rum: (body) => rumApi.aggregateRUMEvents({ body }),
});
